def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    recent = opp[-10:] if n >= 10 else opp
    recent_d = sum(1 for x in recent if x == 'D')
    last_opp = opp[-1]

    if n < 4:
        if opp_d >= 2:
            return 'D'
        return 'C'

    # Hard defectors: stop feeding them.
    if opp_d * 4 >= n * 3:
        return 'D'

    # Near the end, exploit cooperators and avoid being exploited.
    if n >= 94:
        if opp_c * 4 >= n * 3:
            return 'D'
        return 'D' if last_opp == 'D' or opp_d * 2 >= n else 'C'

    # If opponent persistently fails to punish our defections, exploit.
    if n >= 15 and opp_d * 5 <= n:
        my_def_after_coop = 0
        for i in range(1, n):
            if me[i - 1] == 'D' and opp[i] == 'C':
                my_def_after_coop += 1
        if my_def_after_coop >= 2:
            return 'D' if rng.random() < 0.7 else 'C'

    # Retaliate against recent defections, but recover quickly if they return to C.
    if last_opp == 'D':
        if recent_d >= 4:
            return 'D'
        if n >= 2 and opp[-2] == 'C' and recent_d <= 2:
            return 'D' if rng.random() < 0.6 else 'C'
        return 'D'

    # Opponent cooperated. Cooperate, with rare probing of very reliable cooperators.
    if opp_d == 0 and n >= 20:
        if rng.random() < 0.06:
            return 'D'
    return 'C'
